function renderTracks(){let root=$('#tracks');root.replaceChildren();keyElements.clear();if(project.audio){let row=document.createElement('div');row.className='track audio-track';let name=document.createElement('span');name.className='track-name audio-name';name.textContent='♫ '+project.audio.name;name.title=project.audio.name;row.append(name);let rail=createTrackRail(),bar=document.createElement('div');bar.className='audio-bar';bar.textContent='♫ Âm thanh';rail.append(bar);row.append(rail);root.append(row)}for(const [id,item] of [['camera',project.camera],...project.layers.map(l=>[l.id,l])]){normalizeEntity(item);let main=document.createElement('div');main.className='track';let name=document.createElement('span');name.className='track-name';if(id!=='camera')name.append(eyeButton(item));else{let icon=document.createElement('span');icon.className='camera-icon';icon.textContent='◉';name.append(icon)}let label=document.createElement('span');label.className='track-label';label.textContent=id==='camera'?'Camera':item.name;label.dataset.layerId=id;label.title=id==='camera'?'Camera':'Nhấn đúp để đổi tên';label.onclick=()=>id==='camera'?select(id):layerNameClick(id,'timeline');name.append(label);main.append(name);let rail=createTrackRail();if(id!=='camera')rail.append(makeClipBar(item,rail));main.append(rail);root.append(main);
for(const prop of Object.keys(item.value)){let keys=item.keys.filter(k=>k.property===prop);if(!keys.length&&!item.animated[prop])continue;let row=document.createElement('div');row.className='track property-track';let name=document.createElement('span');name.className='track-name property-track-name';name.textContent='↳ '+({position:'Position',rotation:'Rotation',target:'Target',fov:'FOV',scale:'Scale',opacity:'Opacity'}[prop]||prop)+(item.animated[prop]?'':' (tắt)');name.onclick=()=>select(id);row.append(name);let rail=createTrackRail();for(const key of keys){if(id!=='camera'){let bounds=clipBounds(item,project.duration);if(key.time<bounds.start||key.time>=bounds.end&&bounds.end<project.duration)continue}let b=document.createElement('button');keyElements.set(b,key);installAltDuplicate(b,rail,()=>{let chosen=selectedKeys.has(key)?[...selectedKeys]:[key];return chosen.map(k=>({entity:[project.camera,...project.layers].find(e=>e.keys.includes(k)),key:k})).filter(x=>x.entity)},id);b.className='key'+(selectedKeys.has(key)||selectedKey===key?' selected':'');b.textContent='◆';b.style.left=(key.time/project.duration*100)+'%';b.title=prop+' · '+key.time.toFixed(2)+'s';b.onclick=e=>{e.stopPropagation();if(e.altKey)return;if(!(e.ctrlKey||e.metaKey||e.shiftKey)){selectedKeys.clear();selectedClips.clear()}if(selectedKeys.has(key)&&(e.ctrlKey||e.metaKey||e.shiftKey)){selectedKeys.delete(key);selectedKey=null}else{selectedKeys.add(key);selectedKey=key}selected=id;time=key.time;seekAudio();$('#keyTime').value=key.time.toFixed(2);$('#ease').value=key.easing;renderLayerList();renderTracks();applyAtTime();showFields();attach()};b.draggable=true;b.ondragend=e=>{if(!e.clientX)return;let desired=clamp((e.clientX-rail.getBoundingClientRect().left)/rail.clientWidth*project.duration,0,project.duration);let group=selectedKeys.has(key)?[...selectedKeys]:[key];let delta=clamp(desired-key.time,-Math.min(...group.map(k=>k.time)),project.duration-Math.max(...group.map(k=>k.time)));for(const k of group)k.time+=delta;time=key.time;renderTracks();applyAtTime();scheduleSave()};rail.append(b)}row.append(rail);root.append(row)}}}
function createTrackRail(){let rail=document.createElement('div');rail.className='rail';rail.onclick=e=>{time=clamp((e.clientX-rail.getBoundingClientRect().left)/rail.clientWidth*project.duration,0,project.duration);seekAudio();applyAtTime();showFields()};return rail}

function deleteTimelineSelection(keysOnly=false){let keys=new Set(selectedKeys);if(selectedKey)keys.add(selectedKey);let clipIds=keysOnly?new Set():new Set(selectedClips);if(!keys.size&&!clipIds.size){message('Chọn thanh hoặc keyframe cần xóa');return}project.camera.keys=project.camera.keys.filter(k=>!keys.has(k));for(const layer of project.layers)layer.keys=layer.keys.filter(k=>!keys.has(k));if(clipIds.size)project.layers=project.layers.filter(l=>!clipIds.has(l.id));selectedKey=null;selectedKeys.clear();selectedClips.clear();if(selected!=='camera'&&!project.layers.some(l=>l.id===selected))selected='camera';if(clipIds.size)rebuild();else{renderTracks();applyAtTime();showFields()}scheduleSave();message('Đã xóa; Ctrl+Z để hoàn tác')}
function splitSelectedClips(){let ids=selectedClips.size?[...selectedClips]:(selected==='camera'?[]:[selected]);if(!ids.length){message('Chọn thanh layer để cắt');return}let made=[];let next=[];for(const layer of project.layers){if(!ids.includes(layer.id)){next.push(layer);continue}let parts=splitLayerAt(layer,time,project.duration,crypto.randomUUID());if(!parts){next.push(layer);continue}next.push(...parts);made.push(parts[1].id)}if(!made.length){message('Đưa con trỏ thời gian vào giữa thanh cần cắt');return}project.layers=next;selected=made[0];rebuild();for(const id of made)selectedClips.add(id);renderTracks();scheduleSave();message('Đã cắt thanh tại '+time.toFixed(2)+'s')}
// Selection starts only on empty timeline space and remains within the track area.
let selectionDrag=null,suppressRailClick=false;const trackRoot=$('#tracks');
trackRoot.addEventListener('pointerdown',e=>{if(e.button!==0||!e.target.closest('.rail')||e.target.closest('.key,.clip-handle,.clip-bar'))return;selectionDrag={id:e.pointerId,x:e.clientX,y:e.clientY,add:e.ctrlKey||e.metaKey||e.shiftKey,active:false}});
trackRoot.addEventListener('pointermove',e=>{if(!selectionDrag||e.pointerId!==selectionDrag.id)return;const d=selectionDrag;if(!d.active&&Math.hypot(e.clientX-d.x,e.clientY-d.y)<5)return;if(!d.active){d.active=true;trackRoot.setPointerCapture(e.pointerId);d.box=document.createElement('div');d.box.className='selection-box';trackRoot.append(d.box)}const rect=trackRoot.getBoundingClientRect();let x=Math.max(rect.left,Math.min(rect.right,e.clientX)),y=Math.max(rect.top,Math.min(rect.bottom,e.clientY)),left=Math.max(rect.left,Math.min(d.x,x)),top=Math.max(rect.top,Math.min(d.y,y));Object.assign(d.box.style,{left:(left-rect.left)+'px',top:(top-rect.top)+'px',width:Math.abs(x-d.x)+'px',height:Math.abs(y-d.y)+'px'})});
function endSelection(e){if(!selectionDrag||e.pointerId!==selectionDrag.id)return;let d=selectionDrag;selectionDrag=null;if(!d.active)return;let r=d.box.getBoundingClientRect();d.box.remove();if(e.type==='pointercancel')return;if(!d.add){selectedKeys.clear();selectedClips.clear()}const intersects=el=>{let b=el.getBoundingClientRect();return b.right>=r.left&&b.left<=r.right&&b.bottom>=r.top&&b.top<=r.bottom};for(const [el,key] of keyElements)if(intersects(el))selectedKeys.add(key);for(const bar of trackRoot.querySelectorAll('.clip-bar'))if(intersects(bar))selectedClips.add(bar.dataset.layerId);selectedKey=selectedKeys.size?[...selectedKeys][0]:null;suppressRailClick=true;setTimeout(()=>suppressRailClick=false,0);renderTracks();message('Đã chọn '+selectedKeys.size+' keyframe, '+selectedClips.size+' thanh')}
trackRoot.addEventListener('pointerup',endSelection);trackRoot.addEventListener('pointercancel',endSelection);trackRoot.addEventListener('click',e=>{if(suppressRailClick){e.preventDefault();e.stopImmediatePropagation()}},true);
document.addEventListener('keydown',e=>{if(e.ctrlKey||e.metaKey||e.altKey||e.repeat||busy)return;let target=e.target;if(target instanceof HTMLElement&&(target.isContentEditable||/^(INPUT|TEXTAREA|SELECT)$/.test(target.tagName)))return;let k=e.key.toLowerCase();if(k==='c'){e.preventDefault();splitSelectedClips()}else if(k==='d'){e.preventDefault();deleteTimelineSelection()}});
$('#addKey').onclick=()=>{let item=current(),value=selectedValue(),props=Object.keys(value).filter(p=>item.animated[p]);if(!props.length){message('Bật nút ◷ ở đầu dòng thông số cần tạo keyframe');return}selectedKeys.clear();selectedClips.clear();for(const prop of props){selectedKey=putPropertyKey(item,prop,time,value[prop],$('#ease').value);selectedKeys.add(selectedKey)}$('#keyTime').value=time.toFixed(2);renderTracks();scheduleSave()};$('#deleteKey').onclick=()=>deleteTimelineSelection(true);$('#moveKey').onclick=()=>{if(!selectedKey)return;selectedKey.time=clamp(Number($('#keyTime').value),0,project.duration);time=selectedKey.time;seekAudio();renderTracks();applyAtTime();scheduleSave()};$('#ease').onchange=()=>{if(selectedKey){selectedKey.easing=$('#ease').value;applyAtTime();scheduleSave()}};$('#time').oninput=e=>{time=Number(e.target.value);seekAudio();applyAtTime();showFields()};function renderTicks(){let box=$('#ticks');box.replaceChildren();for(let i=0;i<=10;i++){let mark=document.createElement('span');mark.textContent=Number((project.duration*i/10).toFixed(1))+'s';box.append(mark)}}
$('#duration').onchange=e=>{project.duration=clamp(Number(e.target.value)||10,1,Math.max(60,project.duration));e.target.value=project.duration;$('#time').max=project.duration;time=Math.min(time,project.duration);renderTicks();renderTracks();applyAtTime();scheduleSave()};
$('#copyProperties').onclick=()=>{let item=current();if(!item)return;propertyClipboard={type:selected==='camera'?'camera':'layer',value:structuredClone(selectedValue()),color:selected==='camera'?null:(item.color||'#888888')};message('Đã sao chép toàn bộ thông số')};
