$('#camera').onclick=()=>select('camera');$('#cameraKey').onclick=()=>{select('camera');$('#addKey').click()};
function restoreHistory(next){if(!next)return;playing=false;audioElement.pause();$('#play').textContent='▶ Phát';clearTimeout(saveTimer);project=next;selectedKey=null;selectedKeys.clear();selectedClips.clear();if(selected!=='camera'&&!project.layers.some(l=>l.id===selected))selected='camera';time=Math.min(time,project.duration);$('#duration').value=project.duration;$('#time').max=project.duration;renderTicks();rebuild();saveDB().then(()=>message('Đã lưu trên trình duyệt')).catch(e=>message('Lưu thất bại: '+e.message))}
$('#undo').onclick=()=>restoreHistory(history.undo());$('#redo').onclick=()=>restoreHistory(history.redo());
function copyLayer(cut=false){let layer=project.layers.find(l=>l.id===selected);if(!layer){message('Chọn một layer ảnh trước');return}layerClipboard=structuredClone(layer);if(cut){project.layers=project.layers.filter(l=>l.id!==selected);selected='camera';selectedKey=null;rebuild();scheduleSave();message('Đã cắt layer')}else message('Đã sao chép layer')}
function pasteLayer(){if(!layerClipboard){message('Chưa có layer được sao chép');return}let layer=structuredClone(layerClipboard);layer.id=crypto.randomUUID();layer.name=layer.name.replace(/( \(bản sao\))?$/, ' (bản sao)');project.layers.push(layer);selected=layer.id;selectedKey=null;rebuild();scheduleSave();message('Đã dán layer')}
document.addEventListener('keydown',e=>{if(!(e.ctrlKey||e.metaKey)||e.altKey||busy)return;let target=e.target;if(target instanceof HTMLElement&&(target.isContentEditable||/^(INPUT|TEXTAREA|SELECT)$/.test(target.tagName)))return;let k=e.key.toLowerCase();if(k==='z'){e.preventDefault();restoreHistory(e.shiftKey?history.redo():history.undo())}else if(k==='y'){e.preventDefault();restoreHistory(history.redo())}else if(k==='c'){e.preventDefault();copyLayer(false)}else if(k==='x'){e.preventDefault();copyLayer(true)}else if(k==='v'){e.preventDefault();pasteLayer()}});
$('#addAudio').onclick=()=>$('#audioFile').click();$('#audioFile').onchange=async e=>{const file=e.target.files?.[0];if(!file)return;try{let audio=await inspectAudio(file);attachAudio(project,audio);time=0;playing=false;audioElement.pause();$('#play').textContent='▶ Phát';syncAudio();renderTicks();renderTracks();seekAudio();applyAtTime();scheduleSave();message('Đã thêm âm thanh · '+audio.duration.toFixed(2)+' giây')}catch(error){alert('Không nhập được âm thanh: '+error.message)}finally{e.target.value=''}};$('#removeAudio').onclick=()=>{if(!project.audio)return;delete project.audio;playing=false;$('#play').textContent='▶ Phát';syncAudio();renderTracks();applyAtTime();scheduleSave()};
$('#add').onclick=()=>$('#images').click();$('#images').onchange=async e=>{for(const f of e.target.files){if(!['image/png','image/jpeg'].includes(f.type))continue;let src=await new Promise((resolve,reject)=>{let r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(f)});project.layers.push({id:crypto.randomUUID(),name:f.name,src,value:layerDefaults(),keys:[]})}e.target.value='';rebuild();scheduleSave()};$('#deleteLayer').onclick=()=>{if(selected==='camera')return;project.layers=project.layers.filter(l=>l.id!==selected);selected='camera';rebuild();scheduleSave()};$('#reset').onclick=()=>{if(!confirm('Tạo dự án mới? Dự án đang lưu sẽ bị thay thế.'))return;playing=false;audioElement.pause();$('#play').textContent='▶ Phát';project=newProject();selected='camera';time=0;$('#duration').value=10;$('#time').max=10;renderTicks();rebuild();scheduleSave()};
for(const b of document.querySelectorAll('[data-preset]'))b.onclick=()=>{let c=project.camera,base=evaluateEntity(c,0),end=structuredClone(base),p=b.dataset.preset;if(p==='Dolly')end.position[2]-=3;if(p==='Pan'){end.position[0]+=2;end.target[0]+=2}if(p==='Tilt')end.target[1]+=2;if(p==='Orbit'){let x=base.position[0]-base.target[0],z=base.position[2]-base.target[2],a=.4;end.position[0]=base.target[0]+x*Math.cos(a)+z*Math.sin(a);end.position[2]=base.target[2]-x*Math.sin(a)+z*Math.cos(a)}if(p==='Zoom')end.fov=clamp(base.fov-15,1,160);for(const prop of Object.keys(base)){if(JSON.stringify(base[prop])===JSON.stringify(end[prop]))continue;c.animated[prop]=true;putPropertyKey(c,prop,0,base[prop],$('#ease').value);putPropertyKey(c,prop,project.duration,end[prop],$('#ease').value)}select('camera');applyAtTime();scheduleSave()};
$('#savezip').onclick=async()=>{try{let zip=new JSZip(),copy=structuredClone(project);for(const l of copy.layers){let [meta,data]=l.src.split(',');let ext=meta.includes('jpeg')?'jpg':'png';l.asset='assets/'+l.id+'.'+ext;zip.file(l.asset,data,{base64:true});delete l.src}if(copy.audio?.src){let parts=copy.audio.src.split(',');copy.audio.asset='assets/audio-source';zip.file(copy.audio.asset,parts[1],{base64:true});delete copy.audio.src}zip.file('project.json',JSON.stringify(copy,null,2));download(await zip.generateAsync({type:'blob'}),'xuong-vox-project.zip')}catch(e){alert('Không xuất được ZIP: '+e.message)}};$('#openzip').onclick=()=>$('#zip').click();$('#zip').onchange=async e=>{try{const zip=await JSZip.loadAsync(e.target.files[0]);const copy=JSON.parse(await zip.file('project.json').async('string'));if(copy.version!==1||!Array.isArray(copy.layers)||!copy.camera)throw Error('Định dạng dự án không hợp lệ');for(const l of copy.layers){let file=zip.file(l.asset);if(!file)throw Error('Thiếu ảnh '+l.asset);let data=await file.async('base64');l.src='data:image/'+(l.asset.endsWith('.jpg')?'jpeg':'png')+';base64,'+data;delete l.asset}if(copy.audio?.asset){let file=zip.file(copy.audio.asset);if(!file)throw Error('Thiếu tệp âm thanh');let data=await file.async('base64');copy.audio.src='data:'+(copy.audio.mime||'application/octet-stream')+';base64,'+data;delete copy.audio.asset}playing=false;audioElement.pause();$('#play').textContent='▶ Phát';project=copy;normalizeEntity(project.camera);for(const layer of project.layers)normalizeEntity(layer);selected='camera';time=0;$('#duration').value=project.duration;$('#time').max=project.duration;renderTicks();rebuild();scheduleSave()}catch(err){alert('Không mở được ZIP: '+err.message)}e.target.value=''};function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),60000)}
$('#demo').onclick=()=>{if(project.layers.length&&!confirm('Thay cảnh hiện tại bằng cảnh mẫu?'))return;project=newProject();for(let i=0;i<5;i++){let c=document.createElement('canvas');c.width=800;c.height=450;let x=c.getContext('2d');x.fillStyle=['#9eaca9','#718b8a','#546d70','#a03538','#263640'][i];x.fillRect(0,0,800,450);x.fillStyle='rgba(255,255,255,.35)';x.font='bold 80px Arial';x.fillText('LAYER '+(i+1),80,220);let val=layerDefaults();val.position=[(i-2)*.7,(i-2)*.3,-i*1.1];val.scale=[1-i*.08,1-i*.08,1];project.layers.push({id:crypto.randomUUID(),name:'Lớp mẫu '+(i+1)+'.png',src:c.toDataURL(),value:val,keys:[]})}selected='camera';time=0;rebuild();scheduleSave()};
$('#export').onclick=async()=>{if(busy)return;try{if(!window.VideoEncoder||!window.VideoFrame)throw Error('Trình duyệt không hỗ trợ WebCodecs. Hãy thử Chrome hoặc Edge mới.');let config={codec:'avc1.420028',width:1920,height:1080,bitrate:8_000_000,framerate:30,avc:{format:'avc'}};let supported=await VideoEncoder.isConfigSupported(config);if(!supported.supported)throw Error('Trình duyệt hoặc máy này không hỗ trợ mã hóa H.264 1080p.');let aacConfig=project.audio?await audioExportConfig():null;busy=true;playing=false;audioElement.pause();$('#play').textContent='▶ Phát';let target=new ArrayBufferTarget(),muxer=new Muxer({target,video:{codec:'avc',width:1920,height:1080},...(aacConfig?{audio:{codec:'aac',numberOfChannels:2,sampleRate:48000}}:{}),firstTimestampBehavior:'offset',fastStart:'in-memory'}),failure=null;const encoder=new VideoEncoder({output:(chunk,meta)=>muxer.addVideoChunk(chunk,meta),error:e=>failure=e});encoder.configure(config);const originalTime=time;const output=new THREE.WebGLRenderer({antialias:true,preserveDrawingBuffer:true});output.setSize(1920,1080,false);output.setPixelRatio(1);grid.visible=false;gizmo.getHelper().visible=false;cameraHelper.visible=false;cameraIcon.visible=false;active.aspect=16/9;active.updateProjectionMatrix();let frames=Math.ceil(project.duration*30);for(let i=0;i<frames;i++){if(failure)throw failure;time=i/30;applyAtTime();grid.visible=false;gizmo.getHelper().visible=false;cameraHelper.visible=false;cameraIcon.visible=false;output.render(scene,active);let frame=new VideoFrame(output.domElement,{timestamp:Math.round(i*1e6/30),duration:Math.round(1e6/30)});encoder.encode(frame,{keyFrame:i%60===0});frame.close();if(encoder.encodeQueueSize>8)await encoder.flush();if(i%10===0){message('Đang xuất MP4: '+Math.round(i/frames*100)+'%');await new Promise(r=>setTimeout(r,0))}}await encoder.flush();if(failure)throw failure;encoder.close();if(aacConfig){message('Đang xử lý âm thanh…');await encodeAudioTrack(muxer,project.audio.src,project.duration,aacConfig,p=>message('Đang xử lý âm thanh: '+Math.round(p*100)+'%'))}muxer.finalize();output.dispose();time=originalTime;grid.visible=true;gizmo.getHelper().visible=true;cameraHelper.visible=true;cameraIcon.visible=true;applyAtTime();download(new Blob([target.buffer],{type:'video/mp4'}),'xuong-vox.mp4');message('Đã xuất MP4 1080p · 30 FPS')}catch(e){message('Xuất thất bại');alert('Không xuất được MP4: '+e.message)}finally{busy=false;grid.visible=true;gizmo.getHelper().visible=true;cameraHelper.visible=true;cameraIcon.visible=true;resize()}};
function readPresets(){return new Promise((resolve,reject)=>{if(!db)return resolve([]);let r=db.transaction('projects').objectStore('projects').get('camera-presets');r.onsuccess=()=>resolve(r.result||[]);r.onerror=()=>reject(r.error)})}
function writePresets(){return new Promise((resolve,reject)=>{if(!db)return reject(Error('IndexedDB không khả dụng'));let tx=db.transaction('projects','readwrite');tx.objectStore('projects').put(structuredClone(presets),'camera-presets');tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)})}
function renderPresets(){let select=$('#savedPresets'),previous=select.value;select.replaceChildren(new Option('Chọn mẫu đã lưu',''));for(const p of presets)select.add(new Option(p.name,p.id));if(presets.some(p=>p.id===previous))select.value=previous}
try{presets=await readPresets();renderPresets()}catch(e){message('Không tải được mẫu camera: '+e.message)}
$('#savePreset').onclick=async()=>{if(!project.camera.keys.length){alert('Hãy tạo ít nhất một keyframe camera trước khi lưu mẫu.');return}let name=prompt('Tên mẫu keyframe camera:');if(!name?.trim())return;let saved={id:crypto.randomUUID(),name:name.trim(),duration:project.duration,keys:structuredClone(project.camera.keys),animated:structuredClone(project.camera.animated)};presets.push(saved);try{await writePresets();renderPresets();$('#savedPresets').value=saved.id;message('Đã lưu mẫu camera trên trình duyệt')}catch(e){presets.pop();alert('Không lưu được mẫu: '+e.message)}};
$('#applyPreset').onclick=()=>{let p=presets.find(p=>p.id===$('#savedPresets').value);if(!p){alert('Chọn một mẫu camera đã lưu.');return}if(project.camera.keys.length&&!confirm('Thay các keyframe camera hiện tại bằng mẫu đã chọn?'))return;project.camera.keys=structuredClone(p.keys).map(k=>({...k,time:clamp(k.time*project.duration/p.duration,0,project.duration)}));project.camera.animated=structuredClone(p.animated||{});for(const k of project.camera.keys)if(k.property&&project.camera.animated[k.property]===undefined)project.camera.animated[k.property]=true;normalizeEntity(project.camera);select('camera');applyAtTime();showFields();scheduleSave()};
$('#deletePreset').onclick=async()=>{let i=presets.findIndex(p=>p.id===$('#savedPresets').value);if(i<0)return;if(!confirm('Xóa mẫu camera đã chọn?'))return;let removed=presets.splice(i,1)[0];try{await writePresets();renderPresets();message('Đã xóa mẫu camera')}catch(e){presets.splice(i,0,removed);alert('Không xóa được mẫu: '+e.message)}};
let timelineZoom=1;const timelineScroll=$('#timelineScroll'),timelineCanvas=$('#timelineCanvas');function updateTimelineZoom(){let width=timelineScroll.clientWidth;if(width)timelineCanvas.style.width=(150+Math.max(1,width-150)*timelineZoom)+'px'}new ResizeObserver(updateTimelineZoom).observe(timelineScroll);document.querySelector('.timeline').addEventListener('wheel',e=>{if(!e.shiftKey||e.ctrlKey||e.metaKey||e.altKey)return;e.preventDefault();let r=timelineScroll.getBoundingClientRect(),x=clamp(e.clientX-r.left,150,timelineScroll.clientWidth),old=timelineZoom;timelineZoom=clamp(timelineZoom*(e.deltaY<0?1.2:1/1.2),1,10);let anchor=Math.max(0,timelineScroll.scrollLeft+x-150)/old;updateTimelineZoom();timelineScroll.scrollLeft=150+anchor*timelineZoom-x},{passive:false});updateTimelineZoom();
$('#previewZoom').onchange=e=>{$('#cameraFrame').style.transform='scale('+Number(e.target.value)+')'};
const timelineElement=document.querySelector('.timeline'),timelineResize=$('#timelineResize');let timelineDrag=null;function setTimelineHeight(height){const max=Math.max(190,window.innerHeight-260);document.documentElement.style.setProperty('--timeline-height',clamp(height,190,max)+'px')};setTimelineHeight(300);timelineResize.addEventListener('pointerdown',e=>{if(e.button!==0)return;e.preventDefault();timelineDrag={id:e.pointerId,y:e.clientY,height:timelineElement.getBoundingClientRect().height};timelineResize.setPointerCapture(e.pointerId)});timelineResize.addEventListener('pointermove',e=>{if(timelineDrag?.id===e.pointerId)setTimelineHeight(timelineDrag.height+timelineDrag.y-e.clientY)});function endTimelineResize(e){if(timelineDrag?.id===e.pointerId)timelineDrag=null}timelineResize.addEventListener('pointerup',endTimelineResize);timelineResize.addEventListener('pointercancel',endTimelineResize);window.addEventListener('resize',()=>setTimelineHeight(timelineElement.getBoundingClientRect().height));
document.addEventListener('keydown',e=>{if(e.code!=='Space'||e.ctrlKey||e.metaKey||e.altKey||e.repeat||busy)return;const t=e.target;if(t instanceof HTMLElement&&(t.isContentEditable||t.tagName==='TEXTAREA'||t.tagName==='SELECT'||t.tagName==='INPUT'&&t.type!=='range'))return;e.preventDefault();$('#play').click()});
let last=performance.now(),lastFieldsRefresh=0;$('#play').onclick=async()=>{if(playing){playing=false;audioElement.pause();$('#play').textContent='▶ Phát';return}if(time>=project.duration)time=0;playing=true;$('#play').textContent='❚❚ Dừng';last=performance.now();if(loadedAudioSrc){seekAudio();try{await audioElement.play()}catch(e){playing=false;$('#play').textContent='▶ Phát';message('Không phát được âm thanh: '+e.message)}}};function resize(){needsRender=true;let w=$('#customView').clientWidth,h=$('#customView').clientHeight;if(w&&h){renderer.setSize(w,h,false);custom.aspect=w/h;custom.updateProjectionMatrix()}let frame=$('#cameraFrame'),fw=frame.clientWidth,fh=frame.clientHeight;if(fw&&fh)previewRenderer.setSize(fw,fh,false);active.aspect=16/9;active.updateProjectionMatrix();cameraHelper.update()}new ResizeObserver(resize).observe($('#viewport'));function tick(now){requestAnimationFrame(tick);if(playing&&!busy){time=loadedAudioSrc?audioElement.currentTime:time+(now-last)/1000;if(time>=project.duration||loadedAudioSrc&&audioElement.ended){time=project.duration;playing=false;audioElement.pause();$('#play').textContent='▶ Phát'}applyAtTime();if(now-lastFieldsRefresh>=200){showFields();lastFieldsRefresh=now}}last=now;orbit.update();if(busy||!needsRender)return;needsRender=false;grid.visible=false;gizmo.getHelper().visible=false;cameraHelper.visible=false;cameraIcon.visible=false;previewRenderer.render(scene,active);grid.visible=true;gizmo.getHelper().visible=true;cameraHelper.visible=true;cameraIcon.visible=true;renderer.render(scene,custom)}renderTicks();rebuild();resize();requestAnimationFrame(tick);window.__vox={get project(){return project},get time(){return time}};
